    AND role_diag->>''flow_reason''=''ready_to_evaluate'' AND mission_generic_owner.flow_scope_enabled(m.id)
    AND EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=m.id)
    AND mission_generic_owner.c1266_execution_authority_v1(m.id,false,true)->>''runtime_authorized''=''true''
    AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items aw WHERE aw.master_session_id=m.id AND aw.state IN(''ready'',''claimed'',''authorized'',''provider_started'',''uncertain''))
    AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_source_windows aw WHERE aw.master_session_id=m.id AND aw.superseded_at IS NULL AND aw.consumed_message_id IS NULL)
    AND NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions ac WHERE ac.master_session_id=m.id AND ac.closed_at IS NULL);
  END IF;
  staff_tick_view:=jsonb_build_object(''schema_version'',''mission-generic-staff-tick-status/2'',''master_session_id'',m.id,
   ''source_revision'',st_revision,''request_key'',st_original_key,''owned_by_me'',st_owner,''state'',st_state,
   ''work_id'',st_effective_id,''work_state'',st_public_state,''retry_request_key'',st_next_key,
   ''can_resume'',st_resume,''recovery_key'',st_recovery,
   ''acknowledged_retry_from_work_id'',st_ack_predecessor);
  IF nw_mode THEN
   staff_tick_view:=staff_tick_view||jsonb_build_object(''schema_version'',''mission-generic-staff-tick-status/3'',''recovery_kind'',''no_work_progress_receipt'',''original_result_sha256'',nw_original_sha,
    ''recovery_key'',nw_original_key,''retry_request_key'',mission_ai_service_owner.uuid5(st_tick.request_key,''mission-staff-no-dispatch-resume/1:''||st_revision),''acknowledged_recovery_key'',CASE WHEN st_state=''attested'' AND NOT st_blocked AND st_effective_id IS NOT NULL THEN nw_original_key ELSE NULL END,
    ''can_resume'',CASE WHEN st_state=''no_work_released'' THEN st_resume ELSE false END);
  END IF;

 END IF;


 IF staff AND participant AND p_location=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b''::uuid THEN
  journal_settlements:=mission_generic_owner.staff_journal_settlements_v1(m.id,uid);
 END IF;
 IF uf_work.id IS NOT NULL THEN opening_resume49:=mission_generic_owner.opening_ready_resume_proof_v1(uf_work.id,uid);END IF;
 IF uf_work.id IS NOT NULL THEN opening_claim_resume6:=mission_generic_owner.opening_claim_resume_proof_v1(uf_work.id,uid);END IF;
 IF uf_work.id IS NOT NULL THEN c26_count_view:=mission_generic_owner.c1266_count_reconciliation_v1(uf_work.id,uid,false);END IF;
 uf_progress_key:=public.combat_v2_sha256(jsonb_build_object(''session_id'',m.id,
  ''master_version'',m.control_version,''master_state'',m.stato,''run_version'',r.control_version,
  ''run_phase'',r.run_phase,''step_key'',coalesce(private_source_step,r.current_step_key),''processing'',uf_processing,
  ''choice_context'',vchoices,''mechanical_state'',uf_rounds,''unified'',uf_marker,
  ''flow_state'',flow_state,''flow_publication_id'',flow_publication));
 IF role_diag IS NOT NULL THEN uf_progress_key:=public.combat_v2_sha256(jsonb_build_object(''base'',uf_progress_key,''source_revision'',role_diag->>''source_revision'')); END IF;
  IF c26_proof IS NOT NULL THEN
   c26_driver:=jsonb_build_object(''schema_version'',''mission-driver-state/1'',''master_session_id'',m.id,
    ''source_revision'',c26_revision,''kind'',c26_kind,
    ''tick_status'',CASE WHEN c26_kind=''tick'' THEN staff_tick_view ELSE NULL END);
   uf_progress_key:=public.combat_v2_sha256(jsonb_build_object(''base'',uf_progress_key,''driver_state'',c26_driver));
  END IF;
 IF c26_count_view IS NOT NULL THEN uf_progress_key:=public.combat_v2_sha256(jsonb_build_object(''base'',uf_progress_key,''count_reconciliation'',c26_count_view));END IF;
 IF opening_resume49 IS NOT NULL THEN uf_progress_key:=public.combat_v2_sha256(jsonb_build_object(''base'',uf_progress_key,''opening_ready_resume'',opening_resume49));END IF;
 IF opening_claim_resume6 IS NOT NULL THEN uf_progress_key:=public.combat_v2_sha256(jsonb_build_object(''base'',uf_progress_key,''opening_claim_resume'',opening_claim_resume6));END IF;
 return jsonb_build_object(''session_id'',m.id,''step_key'',coalesce(private_source_step,r.current_step_key),''objective'',objective,
 ''processing'',uf_processing,''progress_key'',uf_progress_key,''review_required'',uf_review,
 ''flow_state'',flow_state,''flow_publication_id'',flow_publication,
 ''choices'',case when uf_review or academy then ''[]''::jsonb else vchoices->''choices'' end,
 ''choice_context'',vchoices-''choices'',''state'',m.stato,''can_tick'',active and not uf_review
    and m.id<>''b70b23cf-bad8-475d-a56a-d9c549e35d84''::uuid,
 ''request'',case when active and not uf_review
    and m.id<>''b70b23cf-bad8-475d-a56a-d9c549e35d84''::uuid and not exists(
    select 1 from mission_generic_owner.role_window_cursors c where c.master_session_id=m.id)
    then jsonb_build_object(''schema_version'',''mission-generic-tick/1'',''master_session_id'',m.id) else null end)||coalesce(role_diag,''{}''::jsonb)||CASE WHEN staff_tick_view IS NOT NULL THEN jsonb_build_object(''staff_tick_status'',staff_tick_view) ELSE ''{}''::jsonb END||CASE WHEN c26_driver IS NOT NULL THEN jsonb_build_object(''driver_state'',c26_driver) ELSE ''{}''::jsonb END||CASE WHEN c26_count_view IS NOT NULL THEN jsonb_build_object(''count_reconciliation'',c26_count_view) ELSE ''{}''::jsonb END||CASE WHEN opening_resume49 IS NOT NULL THEN jsonb_build_object(''opening_ready_resume'',opening_resume49) ELSE ''{}''::jsonb END||CASE WHEN opening_claim_resume6 IS NOT NULL THEN jsonb_build_object(''opening_claim_resume'',opening_claim_resume6) ELSE ''{}''::jsonb END||CASE WHEN journal_settlements IS NOT NULL THEN jsonb_build_object(''journal_settlements'',journal_settlements) ELSE ''{}''::jsonb END;
end;
$function$
';
 EXECUTE 'SELECT jsonb_object_agg(v.signature,jsonb_build_object(''signature'',v.signature,''oid'',p.oid::bigint,''owner'',pg_get_userbyid(p.proowner),''acl'',p.proacl::text,''config'',to_jsonb(p.proconfig),''secdef'',p.prosecdef,''volatility'',p.provolatile::text,''language'',l.lanname,''source_md5'',md5(p.prosrc),''ddl_md5'',md5(pg_get_functiondef(p.oid)))) FROM (VALUES (''mission_generic_owner.progress_step(uuid,uuid,uuid)''),(''public.mission_generic_staff_tick_v1(uuid,uuid,text,uuid)''),(''public.mission_generic_dispatch_async_status_v1(uuid,jsonb)''),(''mission_generic_owner.staff_journal_settlements_v1(uuid,uuid)''),(''public.mission_generic_room_state_v1(uuid)'')) v(signature) JOIN pg_proc p ON p.oid=to_regprocedure(v.signature) JOIN pg_language l ON l.oid=p.prolang' INTO heads;
 IF ((SELECT count(*) FROM jsonb_object_keys(heads))=5) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'APPLICATION_RELEASE_HEADER_COUNT' USING ERRCODE='40001';END IF;
 IF (((heads->'mission_generic_owner.progress_step(uuid,uuid,uuid)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"mission_generic_owner.progress_step(uuid,uuid,uuid)","source_md5":"48fa9428af5edef13867ef25412fde7b","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'mission_generic_owner.progress_step(uuid,uuid,uuid)')->>'oid'='50482') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'public.mission_generic_staff_tick_v1(uuid,uuid,text,uuid)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"public.mission_generic_staff_tick_v1(uuid,uuid,text,uuid)","source_md5":"ab1790aed4ada61a36a9ce74869ef9f6","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'public.mission_generic_staff_tick_v1(uuid,uuid,text,uuid)')->>'oid'='109829') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'public.mission_generic_dispatch_async_status_v1(uuid,jsonb)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"public.mission_generic_dispatch_async_status_v1(uuid,jsonb)","source_md5":"3f91b59a8147b1da12956c65472bd3f0","volatility":"s"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'public.mission_generic_dispatch_async_status_v1(uuid,jsonb)')->>'oid'='325045') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'mission_generic_owner.staff_journal_settlements_v1(uuid,uuid)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":false,"signature":"mission_generic_owner.staff_journal_settlements_v1(uuid,uuid)","source_md5":"0f4a976ae6b637cf7673c23428705962","volatility":"s"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'mission_generic_owner.staff_journal_settlements_v1(uuid,uuid)')->>'oid'='341329') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'public.mission_generic_room_state_v1(uuid)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"public.mission_generic_room_state_v1(uuid)","source_md5":"bd9c5559c6a79f63abc2f2962abb56c2","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'public.mission_generic_room_state_v1(uuid)')->>'oid'='50484') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
